function makePrompts(seeds: Seed[], playMode: PlayMode): PromptItem[] {
  const sequence = new Map<string, number>();
  return seeds.map(([gameId, category, text, type, optionA, optionB]) => {
    const key = `${gameId}-${category}`;
    const number = (sequence.get(key) || 0) + 1;
    sequence.set(key, number);
    return {
      id: `spotlight-${playMode}-${key}-${number}`,
      gameId, category, playMode,
      text: gameId === 'would-you-rather' ? `Would you rather ${optionA} or ${optionB}?` : text,
      ...(type ? { type } : {}),
      ...(optionA ? { optionA, optionB } : {}),
      ...(gameId === 'truth-or-sip' ? { forfeit: category === 'kids' ? 'Give your answer in a robot voice, or pass.' : 'Take a sip of any drink, or pass.' } : {}),
    };
  });
}

